//! What a panel is made of: the description that a flow, the browser extension or any other
//! caller hands to CursorPie, and the checks that make it safe to draw.
//!
//! A panel is a small window with a title, a stack of [`Widget`]s (text, fields, lists, a slider, a
//! progress bar) and up to four [`Button`]s. It is plain data (JSON), so it can be written by hand,
//! generated by a flow, or sent by an extension; CursorPie draws it in its own look
//! ([`ui::settings::panel_form`](crate::ui)) and answers with a [`PanelResult`](super::PanelResult).
//!
//! ```json
//! {
//!   "id": "greet",
//!   "title": "Say hello",
//!   "widgets": [
//!     { "type": "input",  "id": "name", "label": "Name", "required": true },
//!     { "type": "toggle", "id": "loud", "label": "Shout" }
//!   ],
//!   "buttons": [ { "id": "go", "label": "Go", "tone": "primary" }, { "id": "no", "label": "Cancel", "cancel": true } ]
//! }
//! ```
//!
//! Nothing here is trusted. [`PanelSpec::checked`] limits the size of everything, removes control
//! characters, makes the ids valid and unique, and drops what cannot be shown, so a spec that comes
//! from a web page's extension cannot make CursorPie draw a huge window or fill memory.

use crate::config::flow::is_var_name;
use serde::{Deserialize, Serialize};
use std::collections::BTreeSet;
use std::fmt;

/// The biggest description taken, in bytes of JSON.
pub const MAX_SPEC_BYTES: usize = 64 * 1024;
/// Most widgets in one panel.
pub const MAX_WIDGETS: usize = 24;
/// Most options in one list.
pub const MAX_OPTIONS: usize = 60;
/// Most buttons in the row at the bottom of a panel.
pub const MAX_BUTTONS: usize = 4;
/// Most buttons in one button grid ([`Widget::Buttons`]), and in all the grids of a panel together.
pub const MAX_GROUP_BUTTONS: usize = 24;
pub const MAX_ACTION_BUTTONS: usize = 48;
/// Most buttons per row of a grid.
pub const MAX_COLUMNS: u8 = 6;
/// Longest icon name or path of a button, in characters.
pub const MAX_ICON_CHARS: usize = 200;
/// An icon that starts with this is a picture file (`file:/home/me/play.png`) instead of the name of
/// an icon of the app. Pictures are only drawn for panels of flows, never for the extension.
pub const FILE_ICON_PREFIX: &str = "file:";
/// Height of a [`Widget::Spacer`]: the least, the most and what it is when the description says none.
pub const SPACER_MIN: f32 = 2.0;
pub const SPACER_MAX: f32 = 200.0;
pub const SPACER_DEFAULT: f32 = 12.0;
/// Longest title, in characters.
pub const MAX_TITLE_CHARS: usize = 80;
/// Longest label, hint, option and button text, in characters.
pub const MAX_LABEL_CHARS: usize = 120;
/// Longest paragraph of a text widget, in characters.
pub const MAX_TEXT_CHARS: usize = 1_000;
/// Longest value of an input, in characters.
pub const MAX_VALUE_CHARS: usize = 2_000;
/// Longest time a panel waits for an answer, in seconds.
pub const MAX_TIMEOUT_S: u32 = 600;
/// How long a panel waits when its description does not say.
pub const DEFAULT_TIMEOUT_S: u32 = 120;
/// Narrowest and widest a panel is drawn, and the width when it does not say (points).
pub const WIDTH_MIN: f32 = 280.0;
pub const WIDTH_MAX: f32 = 640.0;
pub const WIDTH_DEFAULT: f32 = 380.0;
/// Shortest and tallest a panel with a fixed height is drawn (points). Without a height the card
/// is as tall as its content needs.
pub const HEIGHT_MIN: f32 = 200.0;
pub const HEIGHT_MAX: f32 = 900.0;

/// Ids a field may not have: a flow sets these variables itself.
const RESERVED_IDS: [&str; 3] = ["ok", "index", "code"];
/// The color of a [`Widget::Color`] that has none (or a bad one).
pub const DEFAULT_COLOR: &str = "#3b82f6";
/// Widest and narrowest value a number may hold when its description gives no range: it keeps the
/// arithmetic of a flow away from the edge of what a float can say.
pub const NUMBER_LIMIT: f64 = 1e12;

/// For `skip_serializing_if`: a value that is what `Default` makes, so the JSON written by the
/// panel designer stays short and reads like something a person would write.
fn is_default<T: Default + PartialEq>(value: &T) -> bool {
    *value == T::default()
}

/// Where a panel appears.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Place {
    /// Next to the pointer.
    #[default]
    Cursor,
    /// In the middle of the display the pointer is on.
    Center,
    /// At the bottom edge, in the middle.
    Bottom,
    /// At the top edge, in the middle.
    Top,
}

/// The icon in the round badge of the header: the same set as the notice
/// ([`HudKind`](crate::ui::hud::HudKind)).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Icon {
    App,
    Link,
    File,
    Shortcut,
    Command,
    Browser,
    #[default]
    Flow,
}

/// How a text widget is written.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum TextStyle {
    #[default]
    Body,
    Heading,
    Muted,
    Code,
}

/// How a button looks, and which one Enter presses (the first `primary`).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Tone {
    #[default]
    Secondary,
    Primary,
    Danger,
}

/// Where the row of buttons at the bottom of a panel sits.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ButtonAlign {
    /// Against the right edge (the default).
    #[default]
    End,
    /// Against the left edge.
    Start,
    /// In the middle.
    Center,
    /// Every button the same width, filling the whole row.
    Stretch,
}

/// How the options of a [`Widget::Choice`] are laid out.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Layout {
    /// One option per row, with its hint under it.
    #[default]
    List,
    /// Round chips that wrap, for a few short options.
    Chips,
    /// A closed box that opens a list when pressed: one line high however many options there are.
    Dropdown,
}

/// One option of a list. In JSON it is a text (`"red"`) or `{ "value": "red", "label": "Red", "hint": "..." }`.
#[derive(Clone, Debug, Default, PartialEq, Eq, Deserialize)]
#[serde(from = "RawOpt")]
pub struct Opt {
    /// What the answer holds when it is chosen.
    pub value: String,
    /// What is shown (the value when empty).
    pub label: String,
    /// A second, quieter line.
    pub hint: String,
}

#[derive(Deserialize)]
#[serde(untagged)]
enum RawOpt {
    Plain(String),
    Full {
        value: String,
        #[serde(default)]
        label: String,
        #[serde(default)]
        hint: String,
    },
}

impl From<RawOpt> for Opt {
    fn from(raw: RawOpt) -> Self {
        match raw {
            RawOpt::Plain(value) => Opt {
                value,
                label: String::new(),
                hint: String::new(),
            },
            RawOpt::Full { value, label, hint } => Opt { value, label, hint },
        }
    }
}

/// An option is written the short way (a plain text) when it has no label of its own and no hint.
impl Serialize for Opt {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        use serde::ser::SerializeStruct;
        let own_label = !self.label.is_empty() && self.label != self.value;
        if !own_label && self.hint.is_empty() {
            return serializer.serialize_str(&self.value);
        }
        let fields = 1 + usize::from(own_label) + usize::from(!self.hint.is_empty());
        let mut out = serializer.serialize_struct("Opt", fields)?;
        out.serialize_field("value", &self.value)?;
        if own_label {
            out.serialize_field("label", &self.label)?;
        }
        if !self.hint.is_empty() {
            out.serialize_field("hint", &self.hint)?;
        }
        out.end()
    }
}

impl Opt {
    /// An option whose label is its value.
    pub fn new(value: impl Into<String>) -> Self {
        Opt {
            value: value.into(),
            label: String::new(),
            hint: String::new(),
        }
    }
}

/// Hides a widget until a field of the same panel holds a value, so a form can grow as the person
/// answers ("Other: ..." only after *Other* was picked, the advanced options behind a switch).
///
/// In JSON: `{ "id": "mode", "is": "custom" }` shows the widget while the field `mode` is `custom`;
/// without `is` it shows it while the field is *on* (a switch that is on, a box that is not empty, a
/// number that is not 0, a list that has something picked). `"not": true` turns the test round.
/// The field has to be in the same panel ([`PanelSpec::checked`] says when it is not).
#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct ShowIf {
    /// The `id` of the field to look at.
    pub id: String,
    /// The value it has to hold (a switch is `1` or `0`, a multi-choice holds it among its picks);
    /// without it the field only has to be on.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub is: Option<String>,
    /// Show the widget when the test fails instead of when it holds.
    #[serde(default, skip_serializing_if = "is_default")]
    pub not: bool,
}

/// One thing in a panel. The fields ([`Widget::is_field`]) hold what the person enters and are
/// handed back by their `id`; the others only show something. Every widget may carry a
/// [`ShowIf`] (`show_if`).
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "lowercase")]
pub enum Widget {
    /// A paragraph. With an `id` it can be changed while the panel is open (see [`Patch`](super::Patch)).
    Text {
        #[serde(default, skip_serializing_if = "is_default")]
        id: String,
        text: String,
        #[serde(default, skip_serializing_if = "is_default")]
        style: TextStyle,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        show_if: Option<ShowIf>,
    },
    /// A thin line between two groups.
    Separator {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        show_if: Option<ShowIf>,
    },
    /// A box to type in.
    Input {
        id: String,
        #[serde(default, skip_serializing_if = "is_default")]
        label: String,
        #[serde(default, skip_serializing_if = "is_default")]
        hint: String,
        #[serde(default, skip_serializing_if = "is_default")]
        value: String,
        /// Shown as dots (a password).
        #[serde(default, skip_serializing_if = "is_default")]
        secret: bool,
        /// Several lines.
        #[serde(default, skip_serializing_if = "is_default")]
        multiline: bool,
        /// The buttons that confirm refuse an empty box.
        #[serde(default, skip_serializing_if = "is_default")]
        required: bool,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        max_chars: Option<u32>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        show_if: Option<ShowIf>,
    },
    /// A number to type or to step with the `-` and `+` buttons.
    Number {
        id: String,
        #[serde(default, skip_serializing_if = "is_default")]
        label: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        value: Option<f64>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        min: Option<f64>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        max: Option<f64>,
        /// How much the buttons add or take (1 when missing); the answer is snapped to it.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        step: Option<f64>,
        /// Written after the number (`px`, `min`).
        #[serde(default, skip_serializing_if = "is_default")]
        unit: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        show_if: Option<ShowIf>,
    },
    /// A switch.
    Toggle {
        id: String,
        #[serde(default, skip_serializing_if = "is_default")]
        label: String,
        #[serde(default, skip_serializing_if = "is_default")]
        value: bool,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        show_if: Option<ShowIf>,
    },
    /// A number on a rail.
    Slider {
        id: String,
        #[serde(default, skip_serializing_if = "is_default")]
        label: String,
        min: f64,
        max: f64,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        step: Option<f64>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        value: Option<f64>,
        /// Written after the number (`%`, `s`).
        #[serde(default, skip_serializing_if = "is_default")]
        unit: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        show_if: Option<ShowIf>,
    },
    /// A color: the accent swatches of Settings and the color picker of the system. The answer is
    /// the text `#rrggbb`.
    Color {
        id: String,
        #[serde(default, skip_serializing_if = "is_default")]
        label: String,
        #[serde(default, skip_serializing_if = "is_default")]
        value: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        show_if: Option<ShowIf>,
    },
    /// Pick one option.
    Choice {
        id: String,
        #[serde(default, skip_serializing_if = "is_default")]
        label: String,
        options: Vec<Opt>,
        #[serde(default, skip_serializing_if = "is_default")]
        value: String,
        #[serde(default, skip_serializing_if = "is_default")]
        layout: Layout,
        /// Picking an option answers at once (a menu), with the button `pick`.
        #[serde(default, skip_serializing_if = "is_default")]
        submit: bool,
        /// A search box above the list; by default only for a long list.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        search: Option<bool>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        show_if: Option<ShowIf>,
    },
    /// Pick any number of options.
    Multi {
        id: String,
        #[serde(default, skip_serializing_if = "is_default")]
        label: String,
        options: Vec<Opt>,
        #[serde(default, skip_serializing_if = "is_default")]
        values: Vec<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        show_if: Option<ShowIf>,
    },
    /// A bar from 0 to 1; a negative value shows "busy" without a number. Changed with a patch.
    Progress {
        #[serde(default, skip_serializing_if = "is_default")]
        id: String,
        #[serde(default, skip_serializing_if = "is_default")]
        label: String,
        #[serde(default, skip_serializing_if = "is_default")]
        value: f64,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        show_if: Option<ShowIf>,
    },
    /// A grid of buttons, each with an icon of its own: a remote control, a pad of actions.
    /// Pressing one answers the panel with the `id` of that button, like a button of the bottom
    /// row. It holds nothing, so its `id` (optional) only names it.
    Buttons {
        #[serde(default, skip_serializing_if = "is_default")]
        id: String,
        #[serde(default, skip_serializing_if = "is_default")]
        label: String,
        /// Buttons per row, 1 to 6. 0 (the default) takes as many as there are, at most 4.
        #[serde(default, skip_serializing_if = "is_default")]
        columns: u8,
        #[serde(default, skip_serializing_if = "is_default")]
        buttons: Vec<Button>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        show_if: Option<ShowIf>,
    },
    /// Empty room between two groups of widgets.
    Spacer {
        /// Points, 2 to 200 (12 when missing).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        height: Option<f32>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        show_if: Option<ShowIf>,
    },
}

/// A button, at the bottom of the panel or in a [`Widget::Buttons`] grid. The button that was
/// pressed is part of the answer.
#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct Button {
    pub id: String,
    #[serde(default, skip_serializing_if = "is_default")]
    pub label: String,
    #[serde(default, skip_serializing_if = "is_default")]
    pub tone: Tone,
    /// Pressing it (or Esc) closes the panel without an answer.
    #[serde(default, skip_serializing_if = "is_default")]
    pub cancel: bool,
    /// The picture in front of the label (or alone, when there is no label): the name of an icon of
    /// the app (`play`, `skip-forward`, `ico:heart`: Settings shows the list) or, in a panel of a
    /// flow, `file:/path/to/picture.png`.
    #[serde(default, skip_serializing_if = "is_default")]
    pub icon: String,
    /// Pressing it does not make the panel disappear: it stays on screen while the flow does what
    /// the button asked and asks again. (The same for every button: [`PanelSpec::keep_open`].)
    #[serde(default, skip_serializing_if = "is_default")]
    pub keep_open: bool,
}

impl Button {
    /// Limits and cleans this button (see [`PanelSpec::checked`]).
    pub(super) fn clean_in_place(&mut self) -> Result<(), SpecError> {
        check_id(&mut self.id, true, false)?;
        self.label = clean_line(&self.label, MAX_LABEL_CHARS);
        self.icon = clean_line(&self.icon, MAX_ICON_CHARS);
        if self.label.is_empty() && self.icon.is_empty() {
            self.label = self.id.clone();
        }
        Ok(())
    }
}

/// A whole panel.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct PanelSpec {
    /// Names the panel, so a second one with the same id replaces it and it can be updated or
    /// closed from outside. Letters, digits and `_ - . :`.
    #[serde(default, skip_serializing_if = "is_default")]
    pub id: String,
    #[serde(default, skip_serializing_if = "is_default")]
    pub title: String,
    #[serde(default, skip_serializing_if = "is_default")]
    pub subtitle: String,
    #[serde(default, skip_serializing_if = "is_default")]
    pub icon: Icon,
    #[serde(default, skip_serializing_if = "is_default")]
    pub place: Place,
    /// Width in points (280 to 640).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub width: Option<f32>,
    /// Height in points (200 to 900). When missing the card is as tall as its content needs; when
    /// set the card keeps that height (the body scrolls if the content is taller, and the buttons
    /// stay at the bottom).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub height: Option<f32>,
    /// Seconds until the panel gives up (0: never; at most 600; 120 when missing).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub timeout_s: Option<u32>,
    /// `#rrggbb`: the color of the badge and the main button. The accent of Settings when missing.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub accent: Option<String>,
    #[serde(default, skip_serializing_if = "is_default")]
    pub widgets: Vec<Widget>,
    #[serde(default, skip_serializing_if = "is_default")]
    pub buttons: Vec<Button>,
    /// Where the row of buttons at the bottom sits: `end` (right, the default), `start`, `center`
    /// or `stretch` (all the same width).
    #[serde(default, skip_serializing_if = "is_default")]
    pub buttons_align: ButtonAlign,
    /// When a button is pressed the panel stays on screen instead of going away and coming back:
    /// the flow answers the press, and its next *Ask* with the same panel `id` takes the window
    /// over without a blink. It goes away when the flow ends, when a button that cancels is
    /// pressed, or after a few seconds without a new panel.
    #[serde(default, skip_serializing_if = "is_default")]
    pub keep_open: bool,
    /// The panel does not take the keyboard from the app that is in front: for a panel that only
    /// shows how far something has come (the progress panel of a long run), so the keys that the
    /// run sends still reach the app they are for. Where the window system decides that for
    /// itself (macOS, Linux), the request is made and the system has the last word.
    #[serde(default, skip_serializing_if = "is_default")]
    pub passive: bool,
}

/// Why a description was refused.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum SpecError {
    TooBig,
    /// Not JSON, or not shaped like a panel.
    Json(String),
    /// Shaped right, but something in it cannot be used.
    Invalid(String),
}

impl fmt::Display for SpecError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::TooBig => write!(f, "the panel is bigger than {} KiB", MAX_SPEC_BYTES / 1024),
            Self::Json(e) => write!(f, "the panel is not valid: {e}"),
            Self::Invalid(e) => write!(f, "the panel is not valid: {e}"),
        }
    }
}

impl std::error::Error for SpecError {}

/// `text` without control characters (a line break stays only when `multiline`), at most `max`
/// characters long.
fn clean(text: &str, max: usize, multiline: bool) -> String {
    text.chars()
        .filter_map(|c| match c {
            '\n' => Some(if multiline { '\n' } else { ' ' }),
            '\r' => None,
            '\t' => Some(' '),
            c if c.is_control() => None,
            c => Some(c),
        })
        .take(max)
        .collect()
}

/// A paragraph: cleaned, line breaks kept.
pub(super) fn clean_text(text: &str, max: usize) -> String {
    clean(text, max, true)
}

/// A short single-line text: cleaned and trimmed.
pub(super) fn clean_line(text: &str, max: usize) -> String {
    clean(text, max, false).trim().to_string()
}

/// Checks (and trims) an id. `required`: an empty one is refused. `reserved`: the names a flow sets
/// itself are refused.
fn check_id(id: &mut String, required: bool, reserved: bool) -> Result<(), SpecError> {
    *id = id.trim().to_string();
    if id.is_empty() {
        return if required {
            Err(SpecError::Invalid(
                "a field or a button needs an `id`".into(),
            ))
        } else {
            Ok(())
        };
    }
    if !is_var_name(id.as_str()) {
        return Err(SpecError::Invalid(format!(
            "`{id}` is not a good id: use letters, digits and _, and do not start with a digit"
        )));
    }
    if reserved && RESERVED_IDS.contains(&id.as_str()) {
        return Err(SpecError::Invalid(format!(
            "`{id}` is reserved: a flow sets that variable itself"
        )));
    }
    Ok(())
}

/// Cleans the options of a list: texts cut, empty values and repeated values dropped.
pub(super) fn clean_options(options: &mut Vec<Opt>) -> Result<(), SpecError> {
    if options.len() > MAX_OPTIONS {
        return Err(SpecError::Invalid(format!(
            "a list has at most {MAX_OPTIONS} options"
        )));
    }
    let mut seen: BTreeSet<String> = BTreeSet::new();
    options.retain_mut(|o| {
        o.value = clean_line(&o.value, MAX_LABEL_CHARS);
        o.label = clean_line(&o.label, MAX_LABEL_CHARS);
        o.hint = clean_line(&o.hint, MAX_LABEL_CHARS);
        if o.label.is_empty() {
            o.label = o.value.clone();
        }
        !o.value.is_empty() && seen.insert(o.value.clone())
    });
    Ok(())
}

/// `#rrggbb` (or `rrggbb`) as three numbers.
pub fn parse_hex(text: &str) -> Option<[u8; 3]> {
    let t = text.trim().trim_start_matches('#');
    if t.len() != 6 || !t.chars().all(|c| c.is_ascii_hexdigit()) {
        return None;
    }
    let byte = |i: usize| u8::from_str_radix(&t[i..i + 2], 16).ok();
    Some([byte(0)?, byte(2)?, byte(4)?])
}

/// `#rrggbb` in lowercase from three numbers.
pub fn format_hex(rgb: [u8; 3]) -> String {
    format!("#{:02x}{:02x}{:02x}", rgb[0], rgb[1], rgb[2])
}

impl Widget {
    /// The id, when the widget has one.
    pub fn id(&self) -> Option<&str> {
        let id = match self {
            Widget::Text { id, .. }
            | Widget::Input { id, .. }
            | Widget::Number { id, .. }
            | Widget::Toggle { id, .. }
            | Widget::Slider { id, .. }
            | Widget::Color { id, .. }
            | Widget::Choice { id, .. }
            | Widget::Multi { id, .. }
            | Widget::Progress { id, .. }
            | Widget::Buttons { id, .. } => id,
            Widget::Separator { .. } | Widget::Spacer { .. } => return None,
        };
        (!id.is_empty()).then_some(id.as_str())
    }

    /// Whether the person enters something here (its value is part of the answer).
    pub fn is_field(&self) -> bool {
        matches!(
            self,
            Widget::Input { .. }
                | Widget::Number { .. }
                | Widget::Toggle { .. }
                | Widget::Slider { .. }
                | Widget::Color { .. }
                | Widget::Choice { .. }
                | Widget::Multi { .. }
        )
    }

    /// The condition that shows this widget, when it has one.
    pub fn show_if(&self) -> Option<&ShowIf> {
        match self {
            Widget::Text { show_if, .. }
            | Widget::Separator { show_if }
            | Widget::Input { show_if, .. }
            | Widget::Number { show_if, .. }
            | Widget::Toggle { show_if, .. }
            | Widget::Slider { show_if, .. }
            | Widget::Color { show_if, .. }
            | Widget::Choice { show_if, .. }
            | Widget::Multi { show_if, .. }
            | Widget::Progress { show_if, .. }
            | Widget::Buttons { show_if, .. }
            | Widget::Spacer { show_if, .. } => show_if.as_ref(),
        }
    }

    /// Sets or removes the condition that shows this widget.
    pub fn set_show_if(&mut self, condition: Option<ShowIf>) {
        match self {
            Widget::Text { show_if, .. }
            | Widget::Separator { show_if }
            | Widget::Input { show_if, .. }
            | Widget::Number { show_if, .. }
            | Widget::Toggle { show_if, .. }
            | Widget::Slider { show_if, .. }
            | Widget::Color { show_if, .. }
            | Widget::Choice { show_if, .. }
            | Widget::Multi { show_if, .. }
            | Widget::Progress { show_if, .. }
            | Widget::Buttons { show_if, .. }
            | Widget::Spacer { show_if, .. } => *show_if = condition,
        }
    }

    /// Sets the id of a widget that has one (a separator has none and is left alone).
    pub fn set_id(&mut self, new: String) {
        match self {
            Widget::Text { id, .. }
            | Widget::Input { id, .. }
            | Widget::Number { id, .. }
            | Widget::Toggle { id, .. }
            | Widget::Slider { id, .. }
            | Widget::Color { id, .. }
            | Widget::Choice { id, .. }
            | Widget::Multi { id, .. }
            | Widget::Progress { id, .. }
            | Widget::Buttons { id, .. } => *id = new,
            Widget::Separator { .. } | Widget::Spacer { .. } => {}
        }
    }

    /// Limits and cleans this widget (see [`PanelSpec::checked`]).
    fn clean_in_place(&mut self) -> Result<(), SpecError> {
        match self {
            Widget::Separator { .. } => {}
            Widget::Text { id, text, .. } => {
                check_id(id, false, false)?;
                *text = clean(text, MAX_TEXT_CHARS, true);
            }
            Widget::Input {
                id,
                label,
                hint,
                value,
                multiline,
                max_chars,
                ..
            } => {
                check_id(id, true, true)?;
                *label = clean_line(label, MAX_LABEL_CHARS);
                *hint = clean_line(hint, MAX_LABEL_CHARS);
                *max_chars = max_chars.map(|n| n.clamp(1, MAX_VALUE_CHARS as u32));
                let cap = max_chars.map_or(MAX_VALUE_CHARS, |n| n as usize);
                *value = clean(value, cap, *multiline);
            }
            Widget::Number {
                id,
                label,
                value,
                min,
                max,
                step,
                unit,
                ..
            } => {
                check_id(id, true, true)?;
                *label = clean_line(label, MAX_LABEL_CHARS);
                *unit = clean_line(unit, 12);
                *min = (*min).filter(|n| n.is_finite());
                *max = (*max).filter(|n| n.is_finite());
                if let (Some(lo), Some(hi)) = (*min, *max)
                    && lo >= hi
                {
                    return Err(SpecError::Invalid(format!(
                        "the number `{id}` needs a `min` that is smaller than its `max`"
                    )));
                }
                *step = (*step).filter(|s| s.is_finite() && *s > 0.0);
                let (lo, hi) = number_bounds(*min, *max);
                let v = (*value).filter(|v| v.is_finite()).unwrap_or(0.0);
                *value = Some(v.clamp(lo, hi));
            }
            Widget::Toggle { id, label, .. } => {
                check_id(id, true, true)?;
                *label = clean_line(label, MAX_LABEL_CHARS);
            }
            Widget::Slider {
                id,
                label,
                min,
                max,
                step,
                value,
                unit,
                ..
            } => {
                check_id(id, true, true)?;
                *label = clean_line(label, MAX_LABEL_CHARS);
                *unit = clean_line(unit, 12);
                if !(min.is_finite() && max.is_finite() && *min < *max) {
                    return Err(SpecError::Invalid(format!(
                        "the slider `{id}` needs a `min` that is smaller than its `max`"
                    )));
                }
                *step = (*step).filter(|s| s.is_finite() && *s > 0.0);
                let v = (*value).filter(|v| v.is_finite()).unwrap_or(*min);
                *value = Some(v.clamp(*min, *max));
            }
            Widget::Color {
                id, label, value, ..
            } => {
                check_id(id, true, true)?;
                *label = clean_line(label, MAX_LABEL_CHARS);
                *value = parse_hex(value).map_or_else(|| DEFAULT_COLOR.to_string(), format_hex);
            }
            Widget::Choice {
                id,
                label,
                options,
                value,
                ..
            } => {
                check_id(id, true, true)?;
                *label = clean_line(label, MAX_LABEL_CHARS);
                clean_options(options)?;
                let known = options.iter().any(|o| o.value == *value);
                if !known {
                    value.clear();
                }
            }
            Widget::Multi {
                id,
                label,
                options,
                values,
                ..
            } => {
                check_id(id, true, true)?;
                *label = clean_line(label, MAX_LABEL_CHARS);
                clean_options(options)?;
                let mut kept: Vec<String> = Vec::new();
                for v in values.iter() {
                    if options.iter().any(|o| o.value == *v) && !kept.contains(v) {
                        kept.push(v.clone());
                    }
                }
                *values = kept;
            }
            Widget::Progress {
                id, label, value, ..
            } => {
                check_id(id, false, false)?;
                *label = clean_line(label, MAX_LABEL_CHARS);
                *value = if !value.is_finite() || *value < 0.0 {
                    -1.0
                } else {
                    (*value).min(1.0)
                };
            }
            Widget::Buttons {
                id,
                label,
                columns,
                buttons,
                ..
            } => {
                check_id(id, false, false)?;
                *label = clean_line(label, MAX_LABEL_CHARS);
                *columns = (*columns).min(MAX_COLUMNS);
                if buttons.len() > MAX_GROUP_BUTTONS {
                    return Err(SpecError::Invalid(format!(
                        "a grid of buttons has at most {MAX_GROUP_BUTTONS} buttons"
                    )));
                }
                for b in buttons.iter_mut() {
                    b.clean_in_place()?;
                }
            }
            Widget::Spacer { height, .. } => {
                let h = (*height)
                    .filter(|h| h.is_finite())
                    .unwrap_or(SPACER_DEFAULT);
                *height = Some(h.clamp(SPACER_MIN, SPACER_MAX));
            }
        }
        let own = self.id().map(str::to_string);
        self.clean_show_if(own.as_deref())
    }

    /// Cleans the condition of this widget; `own` is the id of the widget itself.
    fn clean_show_if(&mut self, own: Option<&str>) -> Result<(), SpecError> {
        let mut condition = self.show_if().cloned();
        if let Some(c) = condition.as_mut() {
            c.id = c.id.trim().to_string();
            if c.id.is_empty() {
                return Err(SpecError::Invalid(
                    "a `show_if` needs the `id` of a field".into(),
                ));
            }
            if own == Some(c.id.as_str()) {
                return Err(SpecError::Invalid(format!(
                    "`{}` cannot wait for its own value (`show_if`)",
                    c.id
                )));
            }
            c.is = c.is.take().map(|v| clean_line(&v, MAX_LABEL_CHARS));
        }
        self.set_show_if(condition);
        Ok(())
    }

    /// Runs `f` over every text that is shown or entered (not over ids), for filling in the
    /// variables of a flow.
    fn map_text(&mut self, f: &mut dyn FnMut(&str) -> String) {
        match self {
            Widget::Separator { .. } | Widget::Spacer { .. } => {}
            Widget::Buttons { label, buttons, .. } => {
                *label = f(label);
                for b in buttons.iter_mut() {
                    b.label = f(&b.label);
                }
            }
            Widget::Text { text, .. } => *text = f(text),
            Widget::Input {
                label, hint, value, ..
            } => {
                *label = f(label);
                *hint = f(hint);
                *value = f(value);
            }
            Widget::Toggle { label, .. }
            | Widget::Progress { label, .. }
            | Widget::Number { label, .. } => *label = f(label),
            Widget::Color { label, value, .. } => {
                *label = f(label);
                *value = f(value);
            }
            Widget::Slider { label, unit, .. } => {
                *label = f(label);
                *unit = f(unit);
            }
            Widget::Choice {
                label,
                options,
                value,
                ..
            } => {
                *label = f(label);
                *value = f(value);
                for o in options.iter_mut() {
                    o.value = f(&o.value);
                    o.label = f(&o.label);
                    o.hint = f(&o.hint);
                }
            }
            Widget::Multi {
                label,
                options,
                values,
                ..
            } => {
                *label = f(label);
                for v in values.iter_mut() {
                    *v = f(v);
                }
                for o in options.iter_mut() {
                    o.value = f(&o.value);
                    o.label = f(&o.label);
                    o.hint = f(&o.hint);
                }
            }
        }
        if let Some(mut c) = self.show_if().cloned() {
            c.is = c.is.map(|v| f(&v));
            self.set_show_if(Some(c));
        }
    }
}

/// The range a number may hold: what the description says, else [`NUMBER_LIMIT`] on either side.
pub fn number_bounds(min: Option<f64>, max: Option<f64>) -> (f64, f64) {
    (
        min.unwrap_or(-NUMBER_LIMIT).max(-NUMBER_LIMIT),
        max.unwrap_or(NUMBER_LIMIT).min(NUMBER_LIMIT),
    )
}

/// The buttons of a panel that has none: OK and Cancel, or only Cancel for a menu (a list that
/// answers when an option is picked).
pub fn default_buttons(menu: bool) -> Vec<Button> {
    let cancel = Button {
        id: "cancel".into(),
        label: "Cancel".into(),
        tone: Tone::Secondary,
        cancel: true,
        ..Button::default()
    };
    if menu {
        vec![cancel]
    } else {
        vec![
            cancel.clone(),
            Button {
                id: "ok".into(),
                label: "OK".into(),
                tone: Tone::Primary,
                cancel: false,
                ..Button::default()
            },
        ]
    }
}

impl PanelSpec {
    /// Reads a description from JSON text and checks it.
    pub fn parse(json: &str) -> Result<Self, SpecError> {
        if json.len() > MAX_SPEC_BYTES {
            return Err(SpecError::TooBig);
        }
        let spec: PanelSpec =
            serde_json::from_str(json).map_err(|e| SpecError::Json(e.to_string()))?;
        spec.checked()
    }

    /// Reads a description from a JSON value (what the extension sends) and checks it.
    pub fn from_value(value: serde_json::Value) -> Result<Self, SpecError> {
        let spec: PanelSpec =
            serde_json::from_value(value).map_err(|e| SpecError::Json(e.to_string()))?;
        spec.checked()
    }

    /// Limits everything, removes what cannot be shown and fills in what is missing. Safe to call
    /// again on what it returned.
    pub fn checked(mut self) -> Result<Self, SpecError> {
        self.id = self.id.trim().to_string();
        if self.id.chars().count() > 64
            || !self
                .id
                .chars()
                .all(|c| c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '.' | ':'))
        {
            return Err(SpecError::Invalid(
                "the panel `id` may have letters, digits and _ - . : (at most 64)".into(),
            ));
        }
        self.title = clean_line(&self.title, MAX_TITLE_CHARS);
        self.subtitle = clean_line(&self.subtitle, MAX_LABEL_CHARS);
        self.width = self.width.map(|w| {
            if w.is_finite() {
                w.clamp(WIDTH_MIN, WIDTH_MAX)
            } else {
                WIDTH_DEFAULT
            }
        });
        // a height that is not a number means "as tall as the content needs"
        self.height = self
            .height
            .filter(|h| h.is_finite())
            .map(|h| h.clamp(HEIGHT_MIN, HEIGHT_MAX));
        self.timeout_s = Some(
            self.timeout_s
                .unwrap_or(DEFAULT_TIMEOUT_S)
                .min(MAX_TIMEOUT_S),
        );
        self.accent = self.accent.take().filter(|a| parse_hex(a).is_some());

        if self.widgets.len() > MAX_WIDGETS {
            return Err(SpecError::Invalid(format!(
                "a panel has at most {MAX_WIDGETS} widgets"
            )));
        }
        let mut seen: BTreeSet<String> = BTreeSet::new();
        for w in &mut self.widgets {
            w.clean_in_place()?;
            if let Some(id) = w.id()
                && !seen.insert(id.to_string())
            {
                return Err(SpecError::Invalid(format!("the id `{id}` is used twice")));
            }
        }

        let field_ids: BTreeSet<&str> = self
            .widgets
            .iter()
            .filter(|w| w.is_field())
            .filter_map(Widget::id)
            .collect();
        for w in &self.widgets {
            if let Some(c) = w.show_if()
                && !field_ids.contains(c.id.as_str())
            {
                return Err(SpecError::Invalid(format!(
                    "`show_if` waits for the field `{}`, and the panel has no such field",
                    c.id
                )));
            }
        }

        if self.buttons.len() > MAX_BUTTONS {
            return Err(SpecError::Invalid(format!(
                "a panel has at most {MAX_BUTTONS} buttons"
            )));
        }
        let mut button_ids: BTreeSet<String> = BTreeSet::new();
        for b in &mut self.buttons {
            b.clean_in_place()?;
            if !button_ids.insert(b.id.clone()) {
                return Err(SpecError::Invalid(format!(
                    "the button `{}` is used twice",
                    b.id
                )));
            }
        }
        // the buttons of the grids answer with their ids too, so they may not repeat either
        let mut grouped = 0usize;
        for w in &self.widgets {
            if let Widget::Buttons { buttons, .. } = w {
                grouped += buttons.len();
                for b in buttons {
                    if !button_ids.insert(b.id.clone()) {
                        return Err(SpecError::Invalid(format!(
                            "the button `{}` is used twice",
                            b.id
                        )));
                    }
                }
            }
        }
        if grouped > MAX_ACTION_BUTTONS {
            return Err(SpecError::Invalid(format!(
                "a panel has at most {MAX_ACTION_BUTTONS} buttons in its grids"
            )));
        }
        if self.buttons.is_empty() {
            // a panel made of a grid of buttons answers when one is pressed: it only needs a way out
            let menu = self.widgets.iter().any(|w| match w {
                Widget::Choice { submit: true, .. } => true,
                Widget::Buttons { buttons, .. } => !buttons.is_empty(),
                _ => false,
            });
            self.buttons = default_buttons(menu);
        }
        Ok(self)
    }

    /// Runs `f` over every text that is shown or entered (titles, labels, options, values; not
    /// ids), to fill in `{{variables}}`. Call [`checked`](Self::checked) again afterwards: a filled-in
    /// text may be longer than the limit.
    pub fn map_text(&mut self, f: &mut dyn FnMut(&str) -> String) {
        self.title = f(&self.title);
        self.subtitle = f(&self.subtitle);
        for w in &mut self.widgets {
            w.map_text(f);
        }
        for b in &mut self.buttons {
            b.label = f(&b.label);
        }
    }

    /// The accent of the panel, when it has one.
    pub fn accent_rgb(&self) -> Option<[u8; 3]> {
        self.accent.as_deref().and_then(parse_hex)
    }

    /// The width to draw at.
    pub fn width_or_default(&self) -> f32 {
        self.width.unwrap_or(WIDTH_DEFAULT)
    }

    /// Whether the panel answers when an option is picked, so Enter has nothing to confirm.
    pub fn is_menu(&self) -> bool {
        self.widgets
            .iter()
            .any(|w| matches!(w, Widget::Choice { submit: true, .. }))
    }

    /// Every button of the panel: the row at the bottom first, then the buttons of the grids in
    /// the order of the widgets.
    pub fn all_buttons(&self) -> impl Iterator<Item = &Button> {
        self.buttons.iter().chain(self.widgets.iter().flat_map(|w| {
            let group: &[Button] = match w {
                Widget::Buttons { buttons, .. } => buttons.as_slice(),
                _ => &[],
            };
            group.iter()
        }))
    }

    /// The button with this `id`, wherever it is.
    pub fn find_button(&self, id: &str) -> Option<&Button> {
        self.all_buttons().find(|b| b.id == id)
    }

    /// Takes away the icons that are picture files. A panel that something outside CursorPie
    /// sends (the browser extension) may not make CursorPie read files of the computer.
    pub fn strip_file_icons(&mut self) {
        fn strip(b: &mut Button) {
            if b.icon.starts_with(FILE_ICON_PREFIX) {
                b.icon.clear();
            }
        }
        for b in &mut self.buttons {
            strip(b);
        }
        for w in &mut self.widgets {
            if let Widget::Buttons { buttons, .. } = w {
                for b in buttons.iter_mut() {
                    strip(b);
                }
            }
        }
    }
}

/// The names of the variables a flow gets from the panel in `json`: the ids of its fields. Reads the
/// description loosely (it may still hold `{{variables}}`), and gives an empty list when it cannot.
pub fn declared_vars(json: &str) -> Vec<String> {
    let Ok(spec) = serde_json::from_str::<PanelSpec>(json) else {
        return Vec::new();
    };
    spec.widgets
        .iter()
        .filter(|w| w.is_field())
        .filter_map(Widget::id)
        .filter(|id| is_var_name(id))
        .map(str::to_string)
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn parse(json: &str) -> Result<PanelSpec, SpecError> {
        PanelSpec::parse(json)
    }

    #[test]
    fn a_small_panel_is_read_and_gets_buttons_and_a_timeout() {
        let s = parse(r#"{"title":"Hi","widgets":[{"type":"input","id":"name","label":"Name"}]}"#)
            .unwrap();
        assert_eq!(s.title, "Hi");
        assert_eq!(s.timeout_s, Some(DEFAULT_TIMEOUT_S));
        let ids: Vec<&str> = s.buttons.iter().map(|b| b.id.as_str()).collect();
        assert_eq!(ids, ["cancel", "ok"]);
        assert!(s.buttons[0].cancel && !s.buttons[1].cancel);
        assert_eq!(s.buttons[1].tone, Tone::Primary);
    }

    #[test]
    fn options_may_be_texts_or_objects() {
        let s = parse(
            r#"{"widgets":[{"type":"choice","id":"c","options":["a",{"value":"b","label":"Bee","hint":"buzz"}],"value":"b"}]}"#,
        )
        .unwrap();
        let Widget::Choice { options, value, .. } = &s.widgets[0] else {
            panic!("choice")
        };
        assert_eq!(options[0].label, "a", "the label is the value when missing");
        assert_eq!(options[1].label, "Bee");
        assert_eq!(options[1].hint, "buzz");
        assert_eq!(value, "b");
    }

    #[test]
    fn a_menu_has_only_a_cancel_button() {
        let s = parse(r#"{"widgets":[{"type":"choice","id":"c","options":["a"],"submit":true}]}"#)
            .unwrap();
        assert!(s.is_menu());
        assert_eq!(s.buttons.len(), 1);
        assert!(s.buttons[0].cancel);
    }

    #[test]
    fn ids_must_be_names_unique_and_not_reserved() {
        assert!(parse(r#"{"widgets":[{"type":"toggle","id":"a b"}]}"#).is_err());
        assert!(parse(r#"{"widgets":[{"type":"toggle","id":"1a"}]}"#).is_err());
        assert!(parse(r#"{"widgets":[{"type":"toggle","id":""}]}"#).is_err());
        assert!(parse(r#"{"widgets":[{"type":"toggle","id":"ok"}]}"#).is_err());
        assert!(
            parse(r#"{"widgets":[{"type":"toggle","id":"a"},{"type":"toggle","id":"a"}]}"#)
                .is_err()
        );
        // a text or a progress bar may have no id, and a button may be called ok
        assert!(parse(r#"{"widgets":[{"type":"text","text":"x"},{"type":"progress"}],"buttons":[{"id":"ok"}]}"#).is_ok());
        // a button id is not a variable, but it must still be unique
        assert!(parse(r#"{"buttons":[{"id":"a"},{"id":"a"}]}"#).is_err());
    }

    #[test]
    fn limits_hold() {
        let many = format!(
            r#"{{"widgets":[{}]}}"#,
            vec![r#"{"type":"separator"}"#; MAX_WIDGETS + 1].join(",")
        );
        assert!(parse(&many).is_err());
        let huge = format!(r#"{{"title":"{}"}}"#, "x".repeat(MAX_SPEC_BYTES));
        assert_eq!(parse(&huge), Err(SpecError::TooBig));
        let long = format!(r#"{{"title":"{}"}}"#, "x".repeat(500));
        assert_eq!(parse(&long).unwrap().title.chars().count(), MAX_TITLE_CHARS);
        assert!(
            parse(r#"{"buttons":[{"id":"a"},{"id":"b"},{"id":"c"},{"id":"d"},{"id":"e"}]}"#)
                .is_err()
        );
        assert_eq!(
            parse(r#"{"timeout_s":99999}"#).unwrap().timeout_s,
            Some(MAX_TIMEOUT_S)
        );
        assert_eq!(parse(r#"{"timeout_s":0}"#).unwrap().timeout_s, Some(0));
        assert_eq!(parse(r#"{"width":5}"#).unwrap().width, Some(WIDTH_MIN));
        assert_eq!(parse(r#"{"height":5}"#).unwrap().height, Some(HEIGHT_MIN));
        assert_eq!(
            parse(r#"{"height":99999}"#).unwrap().height,
            Some(HEIGHT_MAX)
        );
        assert_eq!(parse(r#"{"height":450}"#).unwrap().height, Some(450.0));
        assert_eq!(parse(r#"{"title":"x"}"#).unwrap().height, None);
    }

    #[test]
    fn control_characters_are_removed_and_line_breaks_kept_only_where_they_belong() {
        let s = parse("{\"title\":\"a\\u0007b\\nc\",\"widgets\":[{\"type\":\"text\",\"text\":\"x\\ny\\u0000\"}]}").unwrap();
        assert_eq!(s.title, "ab c");
        let Widget::Text { text, .. } = &s.widgets[0] else {
            panic!("text")
        };
        assert_eq!(text, "x\ny");
    }

    #[test]
    fn a_choice_forgets_a_value_that_is_not_an_option_and_options_are_deduplicated() {
        let s = parse(
            r#"{"widgets":[{"type":"choice","id":"c","options":["a","a","","b"],"value":"zzz"},
                           {"type":"multi","id":"m","options":["x","y"],"values":["y","y","q"]}]}"#,
        )
        .unwrap();
        let Widget::Choice { options, value, .. } = &s.widgets[0] else {
            panic!("choice")
        };
        assert_eq!(options.len(), 2);
        assert!(value.is_empty());
        let Widget::Multi { values, .. } = &s.widgets[1] else {
            panic!("multi")
        };
        assert_eq!(values, &["y"]);
    }

    #[test]
    fn a_slider_needs_a_range_and_keeps_its_value_inside() {
        assert!(parse(r#"{"widgets":[{"type":"slider","id":"s","min":5,"max":5}]}"#).is_err());
        let s = parse(
            r#"{"widgets":[{"type":"slider","id":"s","min":0,"max":10,"value":99,"step":-1}]}"#,
        )
        .unwrap();
        let Widget::Slider { value, step, .. } = &s.widgets[0] else {
            panic!("slider")
        };
        assert_eq!(*value, Some(10.0));
        assert_eq!(*step, None);
    }

    #[test]
    fn progress_is_a_fraction_or_busy() {
        let s =
            parse(r#"{"widgets":[{"type":"progress","value":7},{"type":"progress","value":-3}]}"#)
                .unwrap();
        let v: Vec<f64> = s
            .widgets
            .iter()
            .map(|w| match w {
                Widget::Progress { value, .. } => *value,
                _ => unreachable!(),
            })
            .collect();
        assert_eq!(v, [1.0, -1.0]);
    }

    #[test]
    fn an_unknown_kind_of_widget_is_an_error_not_silence() {
        assert!(matches!(
            parse(r#"{"widgets":[{"type":"banana"}]}"#),
            Err(SpecError::Json(_))
        ));
    }

    #[test]
    fn colors_are_read_and_bad_ones_dropped() {
        assert_eq!(parse_hex("#ff8000"), Some([255, 128, 0]));
        assert_eq!(parse_hex("00ff00"), Some([0, 255, 0]));
        assert_eq!(parse_hex("#fff"), None);
        assert_eq!(parse_hex("#gggggg"), None);
        assert_eq!(parse(r#"{"accent":"red"}"#).unwrap().accent, None);
        assert_eq!(
            parse(r##"{"accent":"#112233"}"##).unwrap().accent_rgb(),
            Some([17, 34, 51])
        );
    }

    #[test]
    fn map_text_fills_texts_and_checked_again_cuts_them() {
        let mut s = parse(
            r#"{"title":"Hello {{n}}","widgets":[{"type":"input","id":"n","value":"{{n}}"},
                {"type":"choice","id":"c","options":["{{n}}"]}],"buttons":[{"id":"go","label":"Go {{n}}"}]}"#,
        )
        .unwrap();
        s.map_text(&mut |t: &str| t.replace("{{n}}", &"x".repeat(200)));
        let s = s.checked().unwrap();
        assert_eq!(s.title.chars().count(), MAX_TITLE_CHARS);
        assert_eq!(s.buttons[0].label.chars().count(), MAX_LABEL_CHARS);
        // ids are not touched
        assert_eq!(s.widgets[0].id(), Some("n"));
    }

    #[test]
    fn a_value_in_a_variable_cannot_add_widgets() {
        // the flow fills variables after reading the JSON, so a quote in a value is only text
        let mut s = parse(r#"{"title":"Hi {{who}}"}"#).unwrap();
        s.map_text(&mut |t: &str| t.replace("{{who}}", r#"x","buttons":[{"id":"evil"}],"y":""#));
        let s = s.checked().unwrap();
        assert!(s.title.contains("evil"));
        assert_eq!(s.buttons.len(), 2, "still OK and Cancel");
    }

    #[test]
    fn the_variables_a_flow_gets_are_the_ids_of_the_fields() {
        let json = r#"{"title":"{{x}}","widgets":[{"type":"text","id":"t","text":"a"},
            {"type":"input","id":"name"},{"type":"toggle","id":"loud"},{"type":"progress","id":"p"}]}"#;
        assert_eq!(declared_vars(json), ["name", "loud"]);
        assert!(declared_vars("not json").is_empty());
    }

    #[test]
    fn a_number_has_a_range_a_step_and_keeps_its_value_inside() {
        assert!(parse(r#"{"widgets":[{"type":"number","id":"n","min":3,"max":3}]}"#).is_err());
        let s = parse(
            r#"{"widgets":[{"type":"number","id":"n","min":0,"max":10,"value":99,"step":-2}]}"#,
        )
        .unwrap();
        let Widget::Number { value, step, .. } = &s.widgets[0] else {
            panic!("number")
        };
        assert_eq!(*value, Some(10.0));
        assert_eq!(*step, None);
        // no range at all is fine: the limit of numbers keeps it away from the edge of a float
        let s = parse(r#"{"widgets":[{"type":"number","id":"n","value":1e30}]}"#).unwrap();
        let Widget::Number { value, .. } = &s.widgets[0] else {
            panic!("number")
        };
        assert_eq!(*value, Some(NUMBER_LIMIT));
        assert!(
            Widget::Number {
                id: "n".into(),
                label: String::new(),
                value: None,
                min: None,
                max: None,
                step: None,
                unit: String::new(),
                show_if: None
            }
            .is_field()
        );
    }

    #[test]
    fn a_color_is_written_the_same_way_or_replaced_by_the_default() {
        let s = parse(r##"{"widgets":[{"type":"color","id":"a","value":"FF8000"},{"type":"color","id":"b","value":"blue"},{"type":"color","id":"c"}]}"##).unwrap();
        let values: Vec<&str> = s
            .widgets
            .iter()
            .map(|w| match w {
                Widget::Color { value, .. } => value.as_str(),
                _ => unreachable!(),
            })
            .collect();
        assert_eq!(values, ["#ff8000", DEFAULT_COLOR, DEFAULT_COLOR]);
        assert_eq!(format_hex([1, 2, 255]), "#0102ff");
    }

    #[test]
    fn a_dropdown_is_a_layout_of_a_choice_and_takes_no_search_box() {
        let s = parse(
            r#"{"widgets":[{"type":"choice","id":"c","layout":"dropdown","options":["a","b"]}]}"#,
        )
        .unwrap();
        let Widget::Choice { layout, .. } = &s.widgets[0] else {
            panic!("choice")
        };
        assert_eq!(*layout, Layout::Dropdown);
    }

    #[test]
    fn show_if_has_to_name_another_field_of_the_panel() {
        let ok = r#"{"widgets":[{"type":"toggle","id":"adv"},
            {"type":"input","id":"x","show_if":{"id":"adv"}},
            {"type":"text","text":"hi","show_if":{"id":" adv ","is":"1","not":true}},
            {"type":"separator","show_if":{"id":"adv"}}]}"#;
        let s = parse(ok).unwrap();
        assert_eq!(
            s.widgets[2].show_if().map(|c| c.id.as_str()),
            Some("adv"),
            "the id is trimmed"
        );
        // a field that is not there, a text or a progress bar (they hold nothing), the widget itself
        assert!(
            parse(r#"{"widgets":[{"type":"input","id":"x","show_if":{"id":"nope"}}]}"#).is_err()
        );
        assert!(parse(r#"{"widgets":[{"type":"text","id":"t","text":"a"},{"type":"input","id":"x","show_if":{"id":"t"}}]}"#).is_err());
        assert!(parse(r#"{"widgets":[{"type":"toggle","id":"a","show_if":{"id":"a"}}]}"#).is_err());
        assert!(parse(r#"{"widgets":[{"type":"toggle","id":"a"},{"type":"toggle","id":"b","show_if":{"id":""}}]}"#).is_err());
    }

    #[test]
    fn map_text_fills_the_value_a_show_if_waits_for() {
        let mut s = parse(
            r#"{"widgets":[{"type":"choice","id":"m","options":["x"]},
            {"type":"text","text":"t","show_if":{"id":"m","is":"{{want}}"}}]}"#,
        )
        .unwrap();
        s.map_text(&mut |t: &str| t.replace("{{want}}", "x"));
        assert_eq!(
            s.widgets[1].show_if().and_then(|c| c.is.as_deref()),
            Some("x")
        );
    }

    #[test]
    fn what_the_designer_writes_is_short_and_reads_back_the_same() {
        let json = r##"{"title":"T","widgets":[
            {"type":"input","id":"name","label":"Name","required":true},
            {"type":"choice","id":"c","layout":"chips","options":["a",{"value":"b","label":"Bee"},{"value":"c","hint":"third"}],"value":"b"},
            {"type":"number","id":"n","min":0,"max":9,"step":3,"unit":"px"},
            {"type":"color","id":"col","value":"#112233"},
            {"type":"toggle","id":"t","show_if":{"id":"c","is":"a"}},
            {"type":"separator"}],
            "buttons":[{"id":"no","cancel":true},{"id":"go","tone":"primary"}]}"##;
        let first = parse(json).unwrap();
        let written = serde_json::to_string(&first).unwrap();
        assert!(
            !written.contains("\"hint\":\"\""),
            "empty texts are left out: {written}"
        );
        assert!(
            !written.contains("\"secret\""),
            "defaults are left out: {written}"
        );
        assert!(
            written.contains(r#""options":["a","#),
            "a plain option is a text: {written}"
        );
        assert_eq!(parse(&written).unwrap(), first);
        // a panel that was not checked yet (what the designer holds) keeps what was typed
        let loose: PanelSpec =
            serde_json::from_str(r#"{"widgets":[{"type":"text","text":"Hi {{who}}"}]}"#).unwrap();
        assert_eq!(
            serde_json::to_string(&loose).unwrap(),
            r#"{"widgets":[{"type":"text","text":"Hi {{who}}"}]}"#
        );
    }

    #[test]
    fn a_grid_of_buttons_is_read_cleaned_and_checked() {
        let s = PanelSpec::parse(
            r#"{"buttons_align":"stretch","keep_open":true,"widgets":[
                {"type":"buttons","columns":9,"buttons":[{"id":"a","icon":" play "},{"id":"b","label":"B"}]},
                {"type":"spacer","height":9999}],
               "buttons":[{"id":"close","cancel":true}]}"#,
        )
        .expect("a good panel");
        assert_eq!(s.buttons_align, ButtonAlign::Stretch);
        assert!(s.keep_open);
        let Widget::Buttons {
            columns, buttons, ..
        } = &s.widgets[0]
        else {
            panic!("a grid");
        };
        assert_eq!(*columns, MAX_COLUMNS);
        assert_eq!(buttons[0].icon, "play");
        assert_eq!(buttons[0].label, "", "an icon alone stays icon only");
        assert_eq!(buttons[1].label, "B");
        assert!(
            matches!(&s.widgets[1], Widget::Spacer { height: Some(h), .. } if *h == SPACER_MAX)
        );
        assert_eq!(s.all_buttons().count(), 3);
        assert_eq!(s.find_button("b").map(|b| b.label.as_str()), Some("B"));
    }

    #[test]
    fn buttons_of_grids_and_of_the_bottom_row_never_share_an_id() {
        assert!(
            PanelSpec::parse(
                r#"{"widgets":[{"type":"buttons","buttons":[{"id":"a"},{"id":"a"}]}]}"#
            )
            .is_err()
        );
        assert!(PanelSpec::parse(
            r#"{"widgets":[{"type":"buttons","buttons":[{"id":"go"}]}],"buttons":[{"id":"go"}]}"#
        )
        .is_err());
        // a grid is what answers: the panel only needs a way out
        let s = PanelSpec::parse(r#"{"widgets":[{"type":"buttons","buttons":[{"id":"go"}]}]}"#)
            .unwrap();
        assert_eq!(s.buttons.len(), 1);
        assert!(s.buttons[0].cancel);
        let many: Vec<String> = (0..25).map(|i| format!(r#"{{"id":"b{i}"}}"#)).collect();
        assert!(
            PanelSpec::parse(&format!(
                r#"{{"widgets":[{{"type":"buttons","buttons":[{}]}}]}}"#,
                many.join(",")
            ))
            .is_err()
        );
    }

    #[test]
    fn pictures_from_files_are_not_kept_for_the_extension() {
        let mut s = PanelSpec::parse(
            r#"{"widgets":[{"type":"buttons","buttons":[{"id":"a","icon":"file:/etc/x.png"},{"id":"b","icon":"play"}]}],
                "buttons":[{"id":"c","icon":"file:~/y.png"}]}"#,
        )
        .unwrap();
        s.strip_file_icons();
        assert_eq!(s.find_button("a").unwrap().icon, "");
        assert_eq!(s.find_button("b").unwrap().icon, "play");
        assert_eq!(s.find_button("c").unwrap().icon, "");
    }
}
